/**
 * Wijesekara keyboard -> Unicode Sinhala, for live typing in a text box.
 *
 * The FM font encoding *is* the Wijesekara layout, so the key table comes
 * from ./fm-table.json ("wijesekara" + "wijesekaraCompose"), generated by the
 * Python service. python/keyframe_sinhala/wijesekara.py is a line-by-line port;
 * python/tests/golden.json key sequences are checked against both.
 *
 * Stateless: every decision is made from the text before the caret, so it
 * keeps working after cursor moves, undo and paste.
 *
 * Kombuva: on the Wijesekara layout ෙ ("f") is typed *before* the consonant.
 * A typed kombuva is inserted as a lone ෙ (prefixed with ZWNJ when it directly
 * follows a consonant, so it is not mistaken for an attached one). When the
 * next consonant arrives the pending ෙ is removed and consonant + ෙ is
 * inserted in Unicode order; "ff" makes ෛ. Keys typed after an attached ෙ
 * complete the split vowel: a -> ේ, d -> ො, (ො) a -> ෝ, ! -> ෞ.
 */

import table from './fm-table.json';

const HAL = '්';
const ZWJ = '‍';
const ZWNJ = '‌';
const KOMBUVA = 'ෙ';
const KOMBUVA2 = 'ෛ';
const PRE_SIGNS = new Set([KOMBUVA, KOMBUVA2, 'ේ', 'ො', 'ෝ', 'ෞ']);

type KeyType = 'consonant' | 'vowel' | 'sign' | 'prebase' | 'mod' | 'repaya' | 'mark' | 'special';
interface KeyEntry { type: KeyType; u: string }

const KEYS: Record<string, KeyEntry> = table.wijesekara as Record<string, KeyEntry>;
const COMPOSE: readonly (readonly [after: string, key: string, result: string])[] = table.wijesekaraCompose.map(
  (r) => [r[0], r[1], r[2]] as const,
);
const CONSONANTS = new Set(table.consonants.map((r) => r[0]).filter((u) => u.length === 1));
/** Split vowels by their FM suffix after the kombuva: '' -> ෙ, 'a' -> ේ, 'd' -> ො ... */
const PRE_BY_SUFFIX = new Map(table.preBase.filter((r) => r[1] === 'f').map((r) => [r[2], r[0]] as const));
const SUFFIX_OF = new Map([...PRE_BY_SUFFIX].map(([s, u]) => [u, s] as const));

const isCons = (ch: string | undefined): boolean => ch !== undefined && CONSONANTS.has(ch);

/** A kombuva typed but not yet attached: [chars to delete, sign]. */
function pendingKombuva(before: string): [number, string] | null {
  const last = before[before.length - 1];
  if (last !== KOMBUVA && last !== KOMBUVA2) return null;
  const prev = before[before.length - 2];
  if (prev === ZWNJ) return [2, last];
  if (prev !== undefined && (isCons(prev) || prev === ZWJ)) return null; // attached
  return [1, last];
}

/** The split-vowel sign at the end of `before` when it belongs to a consonant. */
function attachedPre(before: string): string | null {
  const last = before[before.length - 1];
  if (last === undefined || !PRE_SIGNS.has(last)) return null;
  return isCons(before[before.length - 2]) ? last : null;
}

/** Index where the consonant cluster ending `before` starts (-1 if none). */
function clusterStart(before: string): number {
  let i = before.length - 1;
  if (i < 0 || !isCons(before[i])) return -1;
  while (i >= 3 && before[i - 1] === ZWJ && before[i - 2] === HAL && isCons(before[i - 3])) i -= 3;
  return i;
}

/**
 * Handle one key press. `before` is the text before the caret, `key` is
 * KeyboardEvent.key (a single printable, already shift-applied character).
 * Returns how many characters to delete before the caret and what to insert,
 * or null when the key is not part of the layout (let the browser type it).
 */
export function wijesekaraKey(before: string, key: string): { deleteBack: number; insert: string } | null {
  const entry = Object.prototype.hasOwnProperty.call(KEYS, key) ? KEYS[key] : undefined;
  if (!entry) return null;
  const { type, u } = entry;
  const r = (deleteBack: number, insert: string) => ({ deleteBack, insert });

  // 1. Two-key compositions (w+d -> ආ, r+e -> රු, ...)
  for (const [after, k, res] of COMPOSE) {
    if (k === key && before.endsWith(after)) {
      const start = before.length - after.length;
      if (isCons(after[0]) && start > 0 && before[start - 1] === ZWJ) continue; // ර of a rakaransaya
      return r(after.length, res);
    }
  }

  // 2. Keys that complete a split vowel after an attached kombuva.
  const pre = attachedPre(before);
  if (pre !== null && SUFFIX_OF.has(pre)) {
    const next = PRE_BY_SUFFIX.get(SUFFIX_OF.get(pre)! + key);
    if (next) return r(1, next);
  }

  switch (type) {
    case 'prebase': {
      const pend = pendingKombuva(before);
      if (pend && pend[1] === KOMBUVA) return r(1, KOMBUVA2); // ff -> ෛ (keeps any ZWNJ marker)
      const last = before[before.length - 1];
      const marker = last !== undefined && (isCons(last) || last === ZWJ) ? ZWNJ : '';
      return r(0, marker + KOMBUVA);
    }
    case 'consonant': {
      const pend = pendingKombuva(before);
      if (pend) return r(pend[0], u + pend[1]);
      // touching conjunct in progress (ක්‍ + ෙ) takes the next consonant before the ෙ
      const last = before[before.length - 1];
      if (before.length >= 2 && (last === KOMBUVA || last === KOMBUVA2) && before[before.length - 2] === ZWJ) {
        return r(1, u + last);
      }
      return r(0, u);
    }
    case 'vowel': {
      if (u === 'එ') {
        const pend = pendingKombuva(before);
        if (pend && pend[1] === KOMBUVA) return r(pend[0], 'ඓ'); // f + t -> ඓ
      }
      return r(0, u);
    }
    case 'mod':
      // rakaransaya / yansaya goes before an attached vowel sign
      return pre !== null ? r(1, u + pre) : r(0, u);
    case 'repaya': {
      const tail = pre ?? '';
      const body = before.slice(0, before.length - tail.length);
      const start = clusterStart(body);
      if (start < 0) return r(0, u);
      const cluster = body.slice(start);
      return r(cluster.length + tail.length, u + cluster + tail);
    }
    default:
      return r(0, u);
  }
}

/** Apply a sequence of keystrokes to `text` (tests, previews). */
export function typeWijesekara(keys: string, text = ''): string {
  for (const k of keys) {
    const res = wijesekaraKey(text, k);
    text = res ? text.slice(0, text.length - res.deleteBack) + res.insert : text + k;
  }
  return text;
}

const HINT_ORDER: Record<KeyType, number> = {
  vowel: 0, consonant: 1, prebase: 2, sign: 2, mod: 3, repaya: 3, mark: 3, special: 4,
};

/** Key -> Unicode list for an on-screen reference (vowels, consonants, signs, specials). */
export const WIJESEKARA_HINTS: readonly { key: string; u: string }[] = Object.entries(KEYS)
  .map(([key, e]) => ({ key, u: e.type === 'prebase' ? KOMBUVA : e.u, o: HINT_ORDER[e.type] ?? 9 }))
  .sort((a, b) => a.o - b.o || (a.key.toLowerCase() < b.key.toLowerCase() ? -1 : a.key.toLowerCase() > b.key.toLowerCase() ? 1 : a.key < b.key ? -1 : a.key > b.key ? 1 : 0))
  .map(({ key, u }) => ({ key, u }));
